15	package reverseproxy
16	
17	import (
18		"fmt"
19		"io"
20		"net/http"
21		"sync"
22		"sync/atomic"
23		"time"
24	
25		"go.uber.org/zap"
26		"go.uber.org/zap/zapcore"
27	
28		"github.com/caddyserver/caddy/v2/modules/caddyhttp"
29	)
30	
31	// StreamLogs configures the logging of upgraded streams
32	// such as WebSockets.
33	type StreamLogs struct {
34		// If true, the request that performs the upgrade handshake is not
35		// written to the access log. By default, it is logged.
36		SkipHandshake bool `json:"skip_handshake,omitempty"`
37	
38		// The level at which the log entry written when a stream closes is
39		// emitted: debug, info, warn or error. The entry goes to the access
40		// loggers of the request (see the `logger_name` option of the
41		// Caddyfile `log` directive), and survives the config that created
42		// the stream being reloaded. Default: debug.
43		Level string `json:"level,omitempty"`
44	}
45	
46	// parseStreamLogLevel returns the level named by s, or DEBUG if s is empty.
47	func parseStreamLogLevel(s string) (zapcore.Level, error) {
48		if s == "" {
49			return zapcore.DebugLevel, nil
50		}
51		var level zapcore.Level
52		if err := level.UnmarshalText([]byte(s)); err != nil {
53			return zapcore.DebugLevel, fmt.Errorf("invalid stream log level %q: %v", s, err)
54		}
55		return level, nil
56	}
57	
58	// streamLogLevel returns the level of the stream close log entry.
59	func (h *Handler) streamLogLevel() zapcore.Level {
60		if h.StreamLogs == nil {
61			return zapcore.DebugLevel
62		}
63		// the level was validated at provisioning
64		level, _ := parseStreamLogLevel(h.StreamLogs.Level)
65		return level
66	}
67	
68	// detachedStream is an upgraded stream that is not bound to the
69	// lifecycle of the handler that proxies it, only to its upstream.
70	type detachedStream struct {
71		upstream string
72		conns    []openConnection
73	}
74	
75	// close closes the connections of the stream.
76	func (s *detachedStream) close() error {
77		var err error
78		for _, oc := range s.conns {
79			if closeErr := closeOpenConnection(oc); closeErr != nil && err == nil {
80				err = closeErr
81			}
82		}
83		return err
84	}
85	
86	// closeOpenConnection closes oc, gracefully if possible.
87	func closeOpenConnection(oc openConnection) error {
88		var err error
89		if oc.gracefulClose != nil {
90			err = oc.gracefulClose()
91		}
92		if closeErr := oc.conn.Close(); closeErr != nil && err == nil {
93			err = closeErr
94		}
95		return err
96	}
97	
98	// streamRegistry keeps track of the upstreams that are part of the loaded
99	// configs and of the detached streams going to them, so that a stream can
100	// outlive the handler that created it and still be closed once nothing
101	// in the live config can reach its upstream anymore.
102	type streamRegistry struct {
103		mu   sync.Mutex
104		live map[string]int
105		open map[string]map[*detachedStream]struct{}
106	}
107	
108	func newStreamRegistry() *streamRegistry {
109		return &streamRegistry{
110			live: make(map[string]int),
111			open: make(map[string]map[*detachedStream]struct{}),
112		}
113	}
114	
115	// detachedStreams is shared by all handlers, across config reloads.
116	var detachedStreams = newStreamRegistry()
117	
118	// addLive records that a handler of the live config uses upstreams.
119	func (r *streamRegistry) addLive(upstreams []string) {
120		r.mu.Lock()
121		defer r.mu.Unlock()
122		for _, u := range upstreams {
123			r.live[u]++
124		}
125	}
126	
127	// removeLive records that a handler stopped using upstreams. It returns, and
128	// forgets, the detached streams whose upstream is not used by any handler
129	// anymore; closing them is up to the caller.
130	func (r *streamRegistry) removeLive(upstreams []string) []*detachedStream {
131		r.mu.Lock()
132		defer r.mu.Unlock()
133		var orphaned []*detachedStream
134		for _, u := range upstreams {
135			r.live[u]--
136			if r.live[u] > 0 {
137				continue
138			}
139			delete(r.live, u)
140			for s := range r.open[u] {
141				orphaned = append(orphaned, s)
142			}
143			delete(r.open, u)
144		}
145		return orphaned
146	}
147	
148	// add tracks s until the returned function is called.
149	func (r *streamRegistry) add(s *detachedStream) (remove func()) {
150		r.mu.Lock()
151		defer r.mu.Unlock()
152		if r.open[s.upstream] == nil {
153			r.open[s.upstream] = make(map[*detachedStream]struct{})
154		}
155		r.open[s.upstream][s] = struct{}{}
156		return func() {
157			r.mu.Lock()
158			defer r.mu.Unlock()
159			delete(r.open[s.upstream], s)
160		}
161	}
162	
163	// liveUpstreams returns the distinct upstream keys of h.
164	func (h *Handler) liveUpstreams() []string {
165		var keys []string
166		seen := make(map[string]struct{}, len(h.Upstreams))
167		for _, u := range h.Upstreams {
168			if _, ok := seen[u.Dial]; ok {
169				continue
170			}
171			seen[u.Dial] = struct{}{}
172			keys = append(keys, u.Dial)
173		}
174		return keys
175	}
176	
177	// closeDetachedStreams closes streams and returns the first error.
178	func closeDetachedStreams(streams []*detachedStream) error {
179		var err error
180		for _, s := range streams {
181			if closeErr := s.close(); closeErr != nil && err == nil {
182				err = closeErr
183			}
184		}
185		return err
186	}
187	
188	// streamUpstream returns the key of the upstream that serves req.
189	func streamUpstream(req *http.Request) string {
190		di, ok := GetDialInfo(req.Context())
191		if !ok {
192			return ""
193		}
194		if di.Upstream != nil {
195			return di.Upstream.Dial
196		}
197		return di.String()
198	}
199	
200	// Possible values of the result label of the closed streams metric.
201	const (
202		streamResultCompleted = "completed"
203		streamResultError     = "error"
204		streamResultTimeout   = "timeout"
205		streamResultCanceled  = "canceled"
206		streamResultReload    = "reload"
207	)
208	
209	// upgradedStream is the accounting state of one upgraded stream.
210	type upgradedStream struct {
211		upstream string
212		// closedByCleanup is set when the stream was closed
213		// by the cleanup of the config instead of ending by itself
214		closedByCleanup atomic.Bool
215	}
216	
217	// cleanupConn marks the stream as closed by cleanup when closed.
218	type cleanupConn struct {
219		io.ReadWriteCloser
220		stream *upgradedStream
221	}
222	
223	func (c *cleanupConn) Close() error {
224		c.stream.closedByCleanup.Store(true)
225		return c.ReadWriteCloser.Close()
226	}
227	
228	// logStreamClosed writes the entry that reports a closed stream.
229	func (h *Handler) logStreamClosed(req *http.Request, stream *upgradedStream, result string, duration time.Duration, toBackend, fromBackend int64) {
230		level := h.streamLogLevel()
231		var fields []zapcore.Field
232		for _, logger := range h.streamLoggers(req) {
233			c := logger.Check(level, "stream closed")
234			if c == nil {
235				continue
236			}
237			if fields == nil {
238				fields = []zapcore.Field{
239					zap.Object("request", caddyhttp.LoggableHTTPRequest{Request: req}),
240					zap.String("upstream", stream.upstream),
241					zap.String("result", result),
242					zap.Duration("duration", duration),
243					zap.Int64("bytes_to_backend", toBackend),
244					zap.Int64("bytes_from_backend", fromBackend),
245				}
246			}
247			c.Write(fields...)
248		}
249	}
250	
251	// streamLoggers returns the loggers a stream close entry for req goes to:
252	// the access loggers if access logging is enabled for req, the logger of
253	// the handler otherwise.
254	func (h *Handler) streamLoggers(req *http.Request) []*zap.Logger {
255		if srv, ok := req.Context().Value(caddyhttp.ServerCtxKey).(*caddyhttp.Server); ok {
256			if loggers := srv.AccessLoggers(req); len(loggers) > 0 {
257				return loggers
258			}
259		}
260		return []*zap.Logger{h.logger}
261	}
